import os
import re
from datetime import datetime, timedelta
from collections import defaultdict

# Reference date
reference_date = datetime(2025, 8, 12)
today = reference_date

# Date ranges
date_ranges = {
    'today': (today, today),
    'last_7_days': (today - timedelta(days=6), today),  # 6 days ago to today (7 days inclusive)
    'last_30_days': (today - timedelta(days=29), today),  # 29 days ago to today (30 days inclusive)
    'month_to_date': (datetime(today.year, today.month, 1), today),
}

# Initialize counters
severity_counts = defaultdict(lambda: {'ERROR': 0, 'WARNING': 0, 'INFO': 0})

# Log directory
log_dir = '/app/logs'

# Process all log files
log_files = sorted(os.listdir(log_dir))

for log_file in log_files:
    # Extract date from filename (YYYY-MM-DD_<source>.log)
    match = re.match(r'(\d{4})-(\d{2})-(\d{2})_', log_file)
    if not match:
        continue

    year, month, day = int(match.group(1)), int(match.group(2)), int(match.group(3))
    file_date = datetime(year, month, day)

    # Read the log file
    file_path = os.path.join(log_dir, log_file)
    try:
        with open(file_path, 'r') as f:
            for line in f:
                # Check for severity levels
                if 'ERROR' in line:
                    severity_counts['total']['ERROR'] += 1
                    if file_date == today:
                        severity_counts['today']['ERROR'] += 1
                    if date_ranges['last_7_days'][0] <= file_date <= date_ranges['last_7_days'][1]:
                        severity_counts['last_7_days']['ERROR'] += 1
                    if date_ranges['last_30_days'][0] <= file_date <= date_ranges['last_30_days'][1]:
                        severity_counts['last_30_days']['ERROR'] += 1
                    if date_ranges['month_to_date'][0] <= file_date <= date_ranges['month_to_date'][1]:
                        severity_counts['month_to_date']['ERROR'] += 1

                elif 'WARNING' in line:
                    severity_counts['total']['WARNING'] += 1
                    if file_date == today:
                        severity_counts['today']['WARNING'] += 1
                    if date_ranges['last_7_days'][0] <= file_date <= date_ranges['last_7_days'][1]:
                        severity_counts['last_7_days']['WARNING'] += 1
                    if date_ranges['last_30_days'][0] <= file_date <= date_ranges['last_30_days'][1]:
                        severity_counts['last_30_days']['WARNING'] += 1
                    if date_ranges['month_to_date'][0] <= file_date <= date_ranges['month_to_date'][1]:
                        severity_counts['month_to_date']['WARNING'] += 1

                elif 'INFO' in line:
                    severity_counts['total']['INFO'] += 1
                    if file_date == today:
                        severity_counts['today']['INFO'] += 1
                    if date_ranges['last_7_days'][0] <= file_date <= date_ranges['last_7_days'][1]:
                        severity_counts['last_7_days']['INFO'] += 1
                    if date_ranges['last_30_days'][0] <= file_date <= date_ranges['last_30_days'][1]:
                        severity_counts['last_30_days']['INFO'] += 1
                    if date_ranges['month_to_date'][0] <= file_date <= date_ranges['month_to_date'][1]:
                        severity_counts['month_to_date']['INFO'] += 1
    except Exception as e:
        print(f"Error reading {log_file}: {e}")

# Write CSV file
output_file = '/app/summary.csv'
with open(output_file, 'w') as f:
    f.write('period,severity,count\n')

    periods = ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']
    severities = ['ERROR', 'WARNING', 'INFO']

    for period in periods:
        for severity in severities:
            count = severity_counts[period][severity]
            f.write(f'{period},{severity},{count}\n')

print(f"Summary written to {output_file}")
EOF
